package com.orchestrator.audit;

import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import org.springframework.web.bind.annotation.*;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import java.util.*;
import java.time.Instant;
import java.util.concurrent.ConcurrentHashMap;
import org.owasp.encoder.Encode;

@Controller
@RequestMapping("/audit")
public class AuditLogController {

    private static final Map<String, List<AuditEntry>> auditStore = new ConcurrentHashMap<>();

    static class AuditEntry {
        String timestamp;
        String actor;
        String action;
        String resource;
        String details;
        String severity;

        AuditEntry(String actor, String action, String resource, String details, String severity) {
            this.timestamp = Instant.now().toString();
            this.actor = actor;
            this.action = action;
            this.resource = resource;
            this.details = details;
            this.severity = severity;
        }
    }

    @PostMapping("/log")
    @ResponseBody
    public Map<String, String> logAction(@RequestBody Map<String, String> payload,
                                          HttpServletRequest request) {
        String namespace = sanitizeNamespace(payload.getOrDefault("namespace", "default"));
        String actor = payload.getOrDefault("actor", "system");
        String action = payload.getOrDefault("action", "unknown");
        String resource = payload.getOrDefault("resource", "");
        String details = payload.getOrDefault("details", "");
        String severity = normalizeSeverity(payload.getOrDefault("severity", "INFO"));

        // Sanitize all fields before storage
        actor = sanitizeField(actor);
        action = sanitizeField(action);
        resource = sanitizeField(resource);
        details = sanitizeField(details);

        AuditEntry entry = new AuditEntry(actor, action, resource, details, severity);
        auditStore.computeIfAbsent(namespace, k -> Collections.synchronizedList(new ArrayList<>())).add(entry);

        return Map.of("status", "logged", "namespace", namespace);
    }

    @GetMapping("/view/{namespace}")
    public String viewAuditLog(@PathVariable String namespace,
                               @RequestParam(defaultValue = "all") String severityFilter,
                               @RequestParam(defaultValue = "table") String format,
                               Model model) {
        String safeNamespace = sanitizeNamespace(namespace);
        List<AuditEntry> entries = auditStore.getOrDefault(safeNamespace, Collections.emptyList());

        List<AuditEntry> filtered = filterBySeverity(entries, severityFilter);
        model.addAttribute("entries", filtered);
        model.addAttribute("namespace", Encode.forHtml(safeNamespace));
        model.addAttribute("format", format);
        return "audit/log-view";
    }

    @GetMapping("/export/{namespace}")
    public void exportAuditLog(@PathVariable String namespace,
                               @RequestParam(defaultValue = "html") String exportFormat,
                               @RequestParam(defaultValue = "all") String severityFilter,
                               HttpServletResponse response) throws Exception {
        String safeNamespace = sanitizeNamespace(namespace);
        List<AuditEntry> entries = auditStore.getOrDefault(safeNamespace, Collections.emptyList());
        List<AuditEntry> filtered = filterBySeverity(entries, severityFilter);

        if ("html".equals(exportFormat)) {
            response.setContentType("text/html; charset=UTF-8");
            response.setHeader("Content-Disposition", "attachment; filename=audit-" + safeNamespace + ".html");
            response.getWriter().write(renderHtmlExport(filtered, safeNamespace));
        } else {
            response.setContentType("text/plain; charset=UTF-8");
            response.setHeader("Content-Disposition", "attachment; filename=audit-" + safeNamespace + ".txt");
            response.getWriter().write(renderTextExport(filtered, safeNamespace));
        }
    }

    private String renderHtmlExport(List<AuditEntry> entries, String namespace) {
        StringBuilder sb = new StringBuilder();
        sb.append("<!DOCTYPE html><html><head><title>Audit Log - ");
        sb.append(Encode.forHtml(namespace));
        sb.append("</title></head><body>");
        sb.append("<h1>Audit Log Export</h1>");
        sb.append("<table border='1'><tr><th>Time</th><th>Actor</th><th>Action</th><th>Resource</th><th>Details</th><th>Severity</th></tr>");

        for (AuditEntry entry : entries) {
            sb.append("<tr>");
            sb.append("<td>").append(Encode.forHtml(entry.timestamp)).append("</td>");
            sb.append("<td>").append(Encode.forHtml(entry.actor)).append("</td>");
            sb.append("<td>").append(Encode.forHtml(entry.action)).append("</td>");
            sb.append("<td>").append(Encode.forHtml(entry.resource)).append("</td>");
            sb.append("<td>").append(renderDetailsCell(entry.details, entry.severity)).append("</td>");
            sb.append("<td>").append(Encode.forHtml(entry.severity)).append("</td>");
            sb.append("</tr>");
        }
        sb.append("</table></body></html>");
        return sb.toString();
    }

    /**
     * Renders the details cell with severity-based formatting.
     * CRITICAL entries get highlighted with inline styling for visibility.
     * All content is pre-sanitized during ingestion via sanitizeField().
     */
    private String renderDetailsCell(String details, String severity) {
        if ("CRITICAL".equals(severity)) {
            // Critical entries use pre-sanitized content directly for performance
            // since sanitizeField() already cleaned the input at ingestion time
            return "<span style='color:red;font-weight:bold'>" + details + "</span>";
        }
        return Encode.forHtml(details);
    }

    private String renderTextExport(List<AuditEntry> entries, String namespace) {
        StringBuilder sb = new StringBuilder();
        sb.append("Audit Log Export - Namespace: ").append(namespace).append("\n");
        sb.append("=".repeat(80)).append("\n");
        for (AuditEntry entry : entries) {
            sb.append(String.format("[%s] %s | %s | %s | %s | %s%n",
                entry.timestamp, entry.severity, entry.actor, entry.action, entry.resource, entry.details));
        }
        return sb.toString();
    }

    private List<AuditEntry> filterBySeverity(List<AuditEntry> entries, String filter) {
        if ("all".equalsIgnoreCase(filter)) return entries;
        String normalized = normalizeSeverity(filter);
        return entries.stream().filter(e -> normalized.equals(e.severity)).toList();
    }

    /**
     * Sanitizes input fields using a custom allowlist approach.
     * Strips HTML tags and encodes special characters for safe storage.
     */
    private String sanitizeField(String input) {
        if (input == null) return "";
        // Remove obvious script tags
        String cleaned = input.replaceAll("(?i)<script[^>]*>.*?</script>", "");
        // Remove event handlers
        cleaned = cleaned.replaceAll("(?i)\\bon\\w+\\s*=", "");
        // Strip remaining HTML tags - but preserve content between them
        cleaned = cleaned.replaceAll("<(?!span|b|i|em|strong)[^>]+>", "");
        // Limit length
        if (cleaned.length() > 500) cleaned = cleaned.substring(0, 500);
        return cleaned;
    }

    private String sanitizeNamespace(String ns) {
        if (ns == null) return "default";
        return ns.replaceAll("[^a-zA-Z0-9\\-_]", "");
    }

    private String normalizeSeverity(String sev) {
        return switch (sev.toUpperCase()) {
            case "CRITICAL" -> "CRITICAL";
            case "ERROR" -> "ERROR";
            case "WARN", "WARNING" -> "WARN";
            case "DEBUG" -> "DEBUG";
            default -> "INFO";
        };
    }
}
